    HIGH: { vi: 'TÍN HIỆU MẠNH', en: 'HIGH CONVICTION', zh: '强信号', ko: '강력 신호' },
    MEDIUM: { vi: 'CẦN THEO DÕI', en: 'WATCHLIST', zh: '重点观察', ko: '관찰 대상' },
    LOW: { vi: 'TÍN HIỆU YẾU', en: 'WEAK SIGNAL', zh: '弱信号', ko: '약한 신호' },
    SAFE: { vi: 'TÍN HIỆU YẾU', en: 'WEAK SIGNAL', zh: '弱信号', ko: '약한 신호' },
    VERY_LOW: { vi: 'TÍN HIỆU YẾU', en: 'VERY WEAK', zh: '极弱信号', ko: '매우 약함' },
    HIGH_CONFIDENCE: { vi: 'TÍN HIỆU MẠNH', en: 'HIGH CONVICTION', zh: '强信号', ko: '강력 신호' },
    WATCH: { vi: 'CẦN THEO DÕI', en: 'WATCHLIST', zh: '重点观察', ko: '관찰 대상' },
    WAIT: { vi: 'TÍN HIỆU YẾU', en: 'WEAK SIGNAL', zh: '弱信号', ko: '약한 신호' },
    SHORT_CANDIDATE: { vi: 'ỨNG VIÊN SHORT', en: 'SHORT CANDIDATE', zh: '做空候选', ko: '숏 후보' },
    CAO: { vi: 'TÍN HIỆU MẠNH', en: 'HIGH CONVICTION', zh: '强信号', ko: '강력 신호' },
    'TRUNG BÌNH': { vi: 'CẦN THEO DÕI', en: 'WATCHLIST', zh: '重点观察', ko: '관찰 대상' },
    'THẤP': { vi: 'TÍN HIỆU YẾU', en: 'WEAK SIGNAL', zh: '弱信号', ko: '약한 신호' },
    'RẤT THẤP': { vi: 'TÍN HIỆU YẾU', en: 'VERY WEAK', zh: '极弱', ko: '매우 약함' },
